    {
        int p=(16+I(b,12)+3)&~3;
        int count=BitConverter.ToUInt16(b,p+2); p+=4;
        var r=new Dictionary<string,byte[]>();
        for(int j=0;j<count;j++) {
            int off=I(b,p),len=I(b,p+4);p+=8;int end=Array.IndexOf(b,(byte)0,p);
            string name=Encoding.ASCII.GetString(b,p,end-p);p=(end+4)&~3;
            r[name]=b.AsSpan(off,len).ToArray();
        }
        return r;
    }
    static Dictionary<string,object> Inspect(string path)
    {
        using var stream=File.OpenRead(path); using var pe=new PEReader(stream); var md=pe.GetMetadataReader();
