using System.Reflection;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Xunit.Abstractions;
using Xunit.Sdk;

var root = @"D:\Projects\katlang-scratch\b32-cutover-20261028";
var outDir = Path.Combine(root, "artifacts/validation/alias-unify-1-b32-final-corrections-20261030/final-v2");
if (args.Length > 2) { outDir = Path.Combine(outDir, args[2] + "-inventory"); Directory.CreateDirectory(outDir); }
if (args[0] == "audit")
{
    var rows = new List<object>();
    var mutableStatics = new List<object>();
    foreach (var directory in new[] { "src/KatLang", "tests/KatLang.Tests" })
    foreach (var path in Directory.EnumerateFiles(Path.Combine(root, directory), "*.cs", SearchOption.AllDirectories))
    {
        if (path.Split(Path.DirectorySeparatorChar).Any(p => p is "bin" or "obj")) continue;
        var source = File.ReadAllText(path);
        var tree = CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Preview));
        if (directory.StartsWith("tests"))
            foreach (var field in tree.GetRoot().DescendantNodes().OfType<FieldDeclarationSyntax>())
                if (field.Modifiers.Any(SyntaxKind.StaticKeyword) && !field.Modifiers.Any(SyntaxKind.ReadOnlyKeyword)
                    && !field.Modifiers.Any(SyntaxKind.ConstKeyword))
                    mutableStatics.Add(new { file = Path.GetRelativePath(root, path).Replace('\\', '/'),
                        line = tree.GetLineSpan(field.Span).StartLinePosition.Line + 1,
                        owner = field.Ancestors().OfType<TypeDeclarationSyntax>().First().Identifier.ValueText,
                        fields = field.Declaration.Variables.Select(v => v.Identifier.ValueText).ToArray(),
                        type = field.Declaration.Type.ToString() });
        foreach (var node in tree.GetRoot().DescendantNodes())
        {
            string? target = node switch
            {
                InvocationExpressionSyntax call when call.Expression.ToString().Split('.').Last() is
                    "CreateScope" or "GetResolvedOpenProviders" or "BoundLookupContext" or "LegacyLexicalCandidates" => call.Expression.ToString(),
                ObjectCreationExpressionSyntax creation when creation.Type.ToString().EndsWith("ElaboratedPropertyScope") => creation.Type.ToString(),
                ImplicitObjectCreationExpressionSyntax creation when creation.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault()?.ReturnType.ToString().TrimEnd('?').EndsWith("ElaboratedPropertyScope") == true => "target-typed construction in scope factory",
                _ => null,
            };
            if (target is null) continue;
            var method = node.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault()?.Identifier.ValueText
                ?? node.Ancestors().OfType<ConstructorDeclarationSyntax>().FirstOrDefault()?.Identifier.ValueText ?? "<initializer>";
            var owner = node.Ancestors().OfType<TypeDeclarationSyntax>().FirstOrDefault()?.Identifier.ValueText;
            rows.Add(new { file = Path.GetRelativePath(root, path).Replace('\\', '/'),
                line = tree.GetLineSpan(node.Span).StartLinePosition.Line + 1, owner, method, target,
                expression = node.ToString(), source_sha256 = Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(source))) });
        }
    }
    File.WriteAllText(Path.Combine(outDir, "standalone-source-inventory.json"), JsonSerializer.Serialize(rows, new JsonSerializerOptions { WriteIndented = true }));
    File.WriteAllText(Path.Combine(outDir, "test-mutable-static-inventory.json"), JsonSerializer.Serialize(mutableStatics, new JsonSerializerOptions { WriteIndented = true }));
    Console.WriteLine($"PROGRESS Source audit inventory: {rows.Count} invocations/constructions.");
    return;
}
var projectName = args.Length > 2 ? args[2] : "KatLang.Tests";
var assemblyPath = Path.Combine(root, $"tests/{projectName}/bin/Debug/net11.0/{projectName}.dll");
var directoryPath = Path.GetDirectoryName(assemblyPath)!;
AssemblyLoadContext.Default.Resolving += (_, name) => File.Exists(Path.Combine(directoryPath, name.Name + ".dll"))
    ? AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(directoryPath, name.Name + ".dll")) : null;
var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(assemblyPath);
if (args[0] == "vstest")
{
    var adapter = AssemblyLoadContext.Default.LoadFromAssemblyPath(Path.Combine(directoryPath, "xunit.runner.visualstudio.testadapter.dll"));
    var type = adapter.GetTypes().Single(t => !t.IsAbstract && typeof(Microsoft.VisualStudio.TestPlatform.ObjectModel.Adapter.ITestDiscoverer).IsAssignableFrom(t));
    var actual = (Microsoft.VisualStudio.TestPlatform.ObjectModel.Adapter.ITestDiscoverer)Activator.CreateInstance(type)!;
    var receiver = new AdapterSink();
    actual.DiscoverTests([assemblyPath], new AdapterContext(), receiver, receiver);
    File.WriteAllText(Path.Combine(outDir, "vstest-inventory.json"), JsonSerializer.Serialize(receiver.Rows, new JsonSerializerOptions { WriteIndented = true }));
    Console.WriteLine($"PROGRESS Actual VSTest adapter discovery: {receiver.Rows.Count} cases, {receiver.Rows.Select(r => r.Id).Distinct().Count()} distinct IDs.");
    return;
}
using var sink = new DiscoverySink();
using var discoverer = new XunitTestFrameworkDiscoverer(new ReflectionAssemblyInfo(assembly), new NoSource(), sink);
var options = new Options();
options.SetValue("xunit.discovery.PreEnumerateTheories", true);
options.SetValue("xunit.discovery.SynchronousMessageReporting", true);
