var expanded = new List<object>();
foreach (var test in sink.Deferred)
{
    var method = ((ReflectionMethodInfo)test.TestMethod.Method).MethodInfo;
    var attributes = method.GetCustomAttributes<DataAttribute>().ToArray();
    if (attributes.Length == 0) throw new Exception("Deferred theory has no data: " + test.DisplayName);
    var ordinal = 0;
    for (var attributeIndex = 0; attributeIndex < attributes.Length; attributeIndex++)
    {
        var data = attributes[attributeIndex];
        if (data.GetType() != typeof(Xunit.MemberDataAttribute) && data.GetType() != typeof(Xunit.InlineDataAttribute))
            throw new Exception("Audit custom data discoverer before expansion: " + data.GetType().FullName);
        foreach (var arguments in data.GetData(method))
        {
            var display = TypeUtility.GetDisplayNameWithArguments(test.TestMethod.Method, test.DisplayName, arguments, null);
            expanded.Add(new { Id = test.UniqueID + "/row/" + ordinal++, ParentId = test.UniqueID,
                Class = test.TestMethod.TestClass.Class.Name, Method = test.TestMethod.Method.Name, Display = display,
                Attribute = attributeIndex, AttributeType = data.GetType().FullName,
                ArgumentTypes = arguments.Select(a => a?.GetType().FullName).ToArray(), Skip = data.Skip });
        }
    }
    if (ordinal == 0) throw new Exception("Deferred theory has no rows: " + test.DisplayName);
}
var result = new { mode = args.Length > 1 ? args[1] : "ordinary", runtime = Environment.Version.ToString(),
    processors = Environment.ProcessorCount, server_gc = System.Runtime.GCSettings.IsServerGC,
    assembly_sha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(assemblyPath))),
    cases = records, expanded_rows = expanded, diagnostics = sink.Diagnostics,
    deferred_theories = records.Count(r => r.Kind.Contains("TheoryTestCase")),
    expanded_case_count = records.Count(r => !r.Kind.Contains("TheoryTestCase")) + expanded.Count };
var fixtures = records.Select(r => r.Class).Distinct().Select(name => assembly.GetType(name)!)
    .Where(t => t is not null).SelectMany(t => t.GetInterfaces().Where(i => i.IsGenericType &&
        i.GetGenericTypeDefinition().FullName is "Xunit.IClassFixture`1" or "Xunit.ICollectionFixture`1")
        .Select(i => new { owner = t.FullName, fixture = i.ToString() })).ToArray();
File.WriteAllText(Path.Combine(outDir, "runner-state-" + result.mode + ".json"), JsonSerializer.Serialize(new {
    result.processors, result.server_gc, fixtures,
    collections = sink.Collections.OrderBy(p => p.Key, StringComparer.Ordinal).ToDictionary(p => p.Key, p => p.Value),
    runtime_config = File.ReadAllText(Path.ChangeExtension(assemblyPath, ".runtimeconfig.json"))
