 var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(assemblyPath);
+if (args[0] == "map")
+{
+    using var inventory = JsonDocument.Parse(File.ReadAllText(Path.Combine(outDir,"discovery-inventory-ordinary.json")));
+    var cases=inventory.RootElement.GetProperty("cases").EnumerateArray().Select(c=>new {
+        Class=c.GetProperty("Class").GetString()!,Method=c.GetProperty("Method").GetString()!,Id=c.GetProperty("Id").GetString()!,Display=c.GetProperty("Display").GetString()!
+    }).ToArray();
+    var classes=cases.Select(c=>c.Class).ToHashSet();
+    using var changed=JsonDocument.Parse(File.ReadAllText(Path.Combine(outDir,"changed-methods.json")));
+    var mapped=new List<object>();var chosen=new HashSet<string>();
+    foreach(var row in changed.RootElement.EnumerateArray())
+    {
+        int token=0x06000000|int.Parse(row.GetProperty("row").GetString()!);
+        var method=assembly.ManifestModule.ResolveMethod(token)!;
+        var type=method.DeclaringType!;var owner=type;
+        while(owner is not null && !classes.Contains(owner.FullName!))owner=owner.DeclaringType;
+        if(owner is null)throw new Exception("Unmapped changed method: "+method+" "+type.FullName);
+        chosen.Add(owner.FullName!);
+        var consumers=new List<object>();
+        foreach(var test in cases.Where(c=>c.Class==owner.FullName).Select(c=>c.Method).Distinct())
+        foreach(var testMethod in owner.GetMethods(BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Where(m=>m.Name==test))
+        foreach(var attribute in testMethod.GetCustomAttributesData().Where(a=>a.AttributeType.Name=="MemberDataAttribute"))
+            consumers.Add(new {test,provider=attribute.ConstructorArguments.FirstOrDefault().Value,named=attribute.NamedArguments.Select(a=>new {a.MemberName,value=a.TypedValue.Value?.ToString()}).ToArray()});
+        mapped.Add(new {token,row=token&0xffffff,method=method.Name,declaring_type=type.FullName,owning_test_class=owner.FullName,
+            compiler_generated=type!=owner || method.IsDefined(typeof(System.Runtime.CompilerServices.CompilerGeneratedAttribute),false),
+            coverage="All tests and all expanded rows in the containing test class",member_data_consumers=consumers,
+            tests=cases.Where(c=>c.Class==owner.FullName).Select(c=>c.Method).Distinct().Order().ToArray()});
+    }
+    File.WriteAllText(Path.Combine(outDir,"changed-method-mapping.json"),JsonSerializer.Serialize(new {methods=mapped,classes=chosen.Order().ToArray()},new JsonSerializerOptions{WriteIndented=true}));
+    Console.WriteLine($"PROGRESS Mapped {mapped.Count} changed methods to {chosen.Count} complete test classes.");
+    return;
+}
 if (args[0] == "vstest")
